use crate::tabs::tab::{Tab, TabState};
use crate::tabs::tab_manager::TabManager;
use crate::storage::session::SavedSession;

/// Action plan generated by the Lazy Session Restoration Pipeline
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LazyRestorePlan {
    /// Tab ID to activate and render immediately
    pub active_tab_id: usize,
    /// Target URL for the immediate active tab
    pub active_url: String,
    /// Background tabs registered as lightweight dormant stubs (id, title, url)
    pub dormant_tabs: Vec<(usize, String, String)>,
}

impl LazyRestorePlan {
    pub fn total_tabs(&self) -> usize {
        1 + self.dormant_tabs.len()
    }

    pub fn dormant_count(&self) -> usize {
        self.dormant_tabs.len()
    }
}

/// Lazy Session Restoration Pipeline
///
/// Ensures rapid cold-startup (< 400ms target) by only instantiating and navigating
/// the single foreground active tab. All background tabs are registered in `TabManager`
/// as suspended stubs without allocating rendering resources until explicitly selected by the user.
pub struct LazyRestorePipeline;

impl LazyRestorePipeline {
    /// Ingests a saved session and instantiates tabs inside `TabManager`.
    /// Returns the restoration plan detailing the active foreground URL and registered dormant tabs.
    pub fn restore_session(
        session: &SavedSession,
        default_url: &str,
        tab_manager: &mut TabManager,
    ) -> LazyRestorePlan {
        if session.tabs.is_empty() {
            // No saved tabs, create a single fresh homepage tab
            let id = tab_manager.create_tab(default_url, None);
            return LazyRestorePlan {
                active_tab_id: id,
                active_url: default_url.to_string(),
                dormant_tabs: Vec::new(),
            };
        }

        // Determine which tab should be the active foreground tab
        let target_active_id = session.active_tab_id
            .filter(|&id| session.tabs.iter().any(|t| t.id == id))
            .unwrap_or_else(|| session.tabs[0].id);

        let mut active_tab_id = 0;
        let mut active_url = String::new();
        let mut dormant_tabs = Vec::new();

        for saved_tab in &session.tabs {
            let is_active = saved_tab.id == target_active_id;
            let tab_id = tab_manager.create_tab(&saved_tab.url, Some(&saved_tab.title));

            if let Some(tab) = tab_manager.get_tab_mut(tab_id) {
                tab.is_pinned = saved_tab.is_pinned;
                tab.zoom_factor = saved_tab.zoom_factor;
                if is_active {
                    tab.state = TabState::Active;
                    tab.touch();
                } else {
                    tab.state = TabState::Suspended;
                }
            }

            if is_active {
                active_tab_id = tab_id;
                active_url = saved_tab.url.clone();
            } else {
                dormant_tabs.push((tab_id, saved_tab.title.clone(), saved_tab.url.clone()));
            }
        }

        // Ensure active tab is focused in TabManager
        tab_manager.switch_tab(active_tab_id);

        log::info!(
            "LazyRestorePipeline: Restored {} tabs (1 active: #{} '{}', {} dormant/suspended)",
            1 + dormant_tabs.len(),
            active_tab_id,
            active_url,
            dormant_tabs.len()
        );

        LazyRestorePlan {
            active_tab_id,
            active_url,
            dormant_tabs,
        }
    }

    /// Determines if switching to the specified tab requires a live network/page restoration
    pub fn needs_activation_navigation(tab: &Tab) -> bool {
        tab.is_suspended()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::storage::session::SavedTab;

    #[test]
    fn test_empty_session_restores_default_url() {
        let mut mgr = TabManager::new();
        let empty_session = SavedSession::default();

        let plan = LazyRestorePipeline::restore_session(&empty_session, "https://example.com", &mut mgr);

        assert_eq!(plan.total_tabs(), 1);
        assert_eq!(plan.dormant_count(), 0);
        assert_eq!(plan.active_url, "https://example.com");
        assert_eq!(mgr.tab_count(), 1);
        assert_eq!(mgr.get_active_tab().unwrap().state, TabState::Active);
    }

    #[test]
    fn test_multi_tab_lazy_restoration() {
        let mut mgr = TabManager::new();
        let session = SavedSession {
            tabs: vec![
                SavedTab {
                    id: 1,
                    position: 0,
                    url: "https://youtube.com".to_string(),
                    title: "YouTube".to_string(),
                    is_active: false,
                    is_suspended: false,
                    is_pinned: false,
                    zoom_factor: 1.0,
                },
                SavedTab {
                    id: 2,
                    position: 1,
                    url: "https://news.ycombinator.com".to_string(),
                    title: "Hacker News".to_string(),
                    is_active: true,
                    is_suspended: false,
                    is_pinned: false,
                    zoom_factor: 1.0,
                },
                SavedTab {
                    id: 3,
                    position: 2,
                    url: "https://github.com".to_string(),
                    title: "GitHub".to_string(),
                    is_active: false,
                    is_suspended: false,
                    is_pinned: false,
                    zoom_factor: 1.0,
                },
            ],
            active_tab_id: Some(2),
        };

        let plan = LazyRestorePipeline::restore_session(&session, "https://google.com", &mut mgr);

        assert_eq!(plan.total_tabs(), 3);
        assert_eq!(plan.dormant_count(), 2);
        assert_eq!(plan.active_url, "https://news.ycombinator.com");

        // Verify that the active tab is Active
        let active_tab = mgr.get_tab(plan.active_tab_id).unwrap();
        assert_eq!(active_tab.state, TabState::Active);
        assert_eq!(active_tab.url, "https://news.ycombinator.com");

        // Verify that the background tabs are Suspended (dormant stubs)
        for &(dormant_id, _, _) in &plan.dormant_tabs {
            let dormant = mgr.get_tab(dormant_id).unwrap();
            assert_eq!(dormant.state, TabState::Suspended);
            assert!(LazyRestorePipeline::needs_activation_navigation(dormant));
        }
    }
}

